import os, struct, lzma

base = '/home/prem/Projects/AppleTV/8988ef3518b1f20f95c66d03be3c15eb4e1be2a0/AssetData/payloadv2'

def stream_pbzx(fpath):
    with open(fpath, 'rb') as fp:
        fp.seek(12)
        while True:
            chdr = fp.read(16)
            if len(chdr) < 16: break
            dlen, clen = struct.unpack('>QQ', chdr)
            cdata = fp.read(clen)
            if dlen == clen:
                yield cdata
            else:
                yield lzma.decompress(cdata)

class StreamBuffer:
    def __init__(self, gen):
        self.gen = gen
        self.buf = bytearray()
    def read(self, n):
        while len(self.buf) < n:
            try:
                self.buf.extend(next(self.gen))
            except StopIteration:
                break
        res = bytes(self.buf[:n])
        del self.buf[:n]
        return res

targets = {'Applications/PineBoard.app/PineBoard', 'Applications/HeadBoard.app/HeadBoard'}

for i in [16, 17, 18, 19, 20]:
    fname = f'payload.{i:03d}'
    fpath = os.path.join(base, fname)
    sb = StreamBuffer(stream_pbzx(fpath))
    while True:
        hdr = sb.read(30)
        if len(hdr) < 30: break
        rtype, fsize, mtime, flags, nlen, uid, gid, mode = struct.unpack('>HQQIHHHH', hdr)
        name = sb.read(nlen).decode('utf-8', errors='replace')
        # skip file bytes
        remaining = fsize
        while remaining > 0:
            block = sb.read(min(remaining, 65536))
            if not block: break
            remaining -= len(block)
        if name in targets or 'PineBoard.app' in name or 'HeadBoard.app' in name:
            if rtype == 0x1001:
                print(f'{fname}: {name} (size={fsize}, mode={oct(mode)})')
"
